    /// <summary>
    /// Copies entity values to Sales line.
    /// </summary>
    /// <param name = "_salesOrderLineEntity">_salesOrderLineEntity</param>
    /// <param name = "_salesLine">Sales line</param>
    public void copyToSalesLine(SalesOrderLineV2Entity      _salesOrderLineEntity,
                                SalesLine                   _salesLine)
    {
        InventDim       inventDim;

        inventDim.InventSiteId          = _salesOrderLineEntity.ShippingSiteId;
        inventDim.InventLocationId      = _salesOrderLineEntity.ShippingWarehouseId;
        inventDim   = InventDim::findOrCreate(inventDim);

        _salesLine.SalesId                  = _salesOrderLineEntity.SalesOrderNumber;
        _salesLine.SalesStatus              = _salesOrderLineEntity.SalesOrderLineStatus;

        _salesLine.ItemId                   = _salesOrderLineEntity.ItemNumber;
        _salesLine.itemIdChanged();

        _salesLine.Blocked                  = _salesOrderLineEntity.IsLineStopped;        
        _salesLine.InventDimId              = inventDim.inventDimId;
        _salesLine.SalesQty                 = _salesOrderLineEntity.OrderedSalesQuantity;
        _salesLine.SalesUnit                = _salesOrderLineEntity.SalesUnitSymbol;
        _salesLine.ShippingDateRequested    = _salesOrderLineEntity.RequestedShippingDate;
        _salesLine.ShippingDateConfirmed    = _salesOrderLineEntity.ConfirmedShippingDate;
        _salesLine.CurrencyCode             = _salesOrderLineEntity.CurrencyCode;       

        _salesLine.METSkipQuantityUpdatePrompts = true;
        SalesLine::modifySalesQty(_salesLine,
                                  inventDim,
                                  false,
                                  false);
        
    }
